We will denote the transpose of a vector $x$ of $\mathbb{R}^d$, and more generally, of any matrix $M \in \mathcal{M}_{n\times m}(\mathbb{R})$, by:
\begin{align}
^t\hspace{-0.25mm} x \hspace{5mm} \text{and} \hspace{5mm} ^t\hspace{-0.5mm} M.
\end{align}

\label{DEFIN_Map_b_2_b__P__}
Let $u \in \mathbb{S}^2$. We define $\widehat{\mathfrak{P}}(u)=u' \in \mathbb{S}^2$, where $u'$ is computed according to the following algorithm.
\begin{enumerate}
\item If $u \cdot e_x < 0$, replace $u$ by $-u$. If not, skip this step.
\item Define the value of the variable \emph{contact} to be $\mathfrak{b}$.
\item If $\text{contact} = \mathfrak{a}$, then:\begin{enumerate}
\item Define $p$, $q$ and $v$ as:
\begin{align}
p = u \wedge e_x, \hspace{5mm} q = p \wedge u, \hspace{5mm} v = u - \big(u \cdot e_x\big)e_x.
\end{align}
\item If $q \cdot v > 0$, update the variable $\text{contact} = \mathfrak{b}$, and compute:
\begin{align}
p' = e_y \wedge u, \hspace{5mm} q' = B q.
\end{align}
If instead $q \cdot v < 0$, update the variable $\text{contact} = \mathfrak{c}$, and compute:
\begin{align}
p' = e_z \wedge u, \hspace{5mm} q' = C q.
\end{align}
\end{enumerate}
If $\text{contact} = \mathfrak{b}$, then:\begin{enumerate}
\item Define $p$, $q$ and $v$ as:
\begin{align}
p = u \wedge e_y, \hspace{5mm} q = p \wedge u, \hspace{5mm} v = u - \big(u \cdot e_y\big)e_y.
\end{align}
\item If $q \cdot v > 0$, update the variable $\text{contact} = \mathfrak{c}$, and compute:
\begin{align}
p' = e_z \wedge u, \hspace{5mm} q' = C q.
\end{align}
If instead $q \cdot v < 0$, update the variable $\text{contact} = \mathfrak{a}$, and compute:
\begin{align}
p' = e_x \wedge u, \hspace{5mm} q' = A q.
\end{align}
\end{enumerate}
If $\text{contact} = \mathfrak{c}$, then:\begin{enumerate}
\item Define $p$, $q$ and $v$ as:
\begin{align}
p = u \wedge e_z, \hspace{5mm} q = p \wedge u, \hspace{5mm} v = u - \big(u \cdot e_z\big)e_z.
\end{align}
\item If $q \cdot v > 0$, update the variable $\text{contact} = \mathfrak{a}$, and compute:
\begin{align}
p' = e_x \wedge u, \hspace{5mm} q' = A q.
\end{align}
If instead $q \cdot v < 0$, update the variable $\text{contact} = \mathfrak{b}$, and compute:
\begin{align}
p' = e_y \wedge u, \hspace{5mm} q' = B q.
\end{align}
\end{enumerate}
\item Compute $u' = q' \wedge p'$. Replace $u$ by $u'$.
\item If $\text{contact} = \mathfrak{b}$, stop the algorithm and return $u'$ as the result of the algorithm.\\
If not, repeat the algorithm starting from step $3$.
\end{enumerate}

We define the \emph{domain of the $\mathfrak{b}$-to-$\mathfrak{b}$ mapping $\widehat{\mathfrak{P}}$} as the subset, denoted by $X$, of the two-dimensional unit sphere $\mathbb{S}^2$ defined as:
\begin{align}
\label{EQUATDefinDomai_X_P_}
X = \{x^2+y^2+z^2 = 1\}\cap \Big[ \{x\geq 0, z\leq 0\} \cup \{x\leq 0, z\geq 0\} \Big].
\end{align}

\label{THEOR__P__FukngLinea}
Let $X\subset \mathbb{R}^3$ be defined in \eqref{EQUATDefinDomai_X_P_}. Then the $\mathfrak{b}$-to-$\mathfrak{b}$ mapping $\widehat{\mathfrak{P}}:X \to \mathbb{S}^2$ introduced in Definition \ref{DEFIN_Map_b_2_b__P__}, defined on $X$, coincides almost everywhere with a piecewise projective linear transformation, whose associated piecewise linear transformation $\mathfrak{P}$ is given by:
\begin{align}
\label{EQUATSpherReduc_btobLineaVersi}
\mathfrak{P}\begin{pmatrix} x \\ y \\ z \end{pmatrix} = \left\{
\begin{array}{cl}
\hspace{-3mm}P_1 \begin{pmatrix} x \\ y \\ z \end{pmatrix} = \begin{pmatrix}
r (\alpha y - x) \\ \alpha (\alpha y - x) - ry + r\alpha z \\ r^2 z
\end{pmatrix} & \hspace{-3mm}\text{if } x > 0,\ z < 0,\ y > 0,\ \alpha y - x > 0, \\
& \\
\hspace{-1.5mm} P_2 \begin{pmatrix} x \\ y \\ z \end{pmatrix} =
\begin{pmatrix}
-r (\alpha y -x) \\ -\alpha (\alpha y - x) - \alpha (\alpha y -z) + ry \\ -r(\alpha y - z)
\end{pmatrix} & \hspace{-3mm}\text{if } x > 0,\ z < 0,\ y > 0,\ \alpha y - x < 0, \\
& \\
\hspace{-3mm}P_3 \begin{pmatrix} x \\ y \\ z \end{pmatrix} =
\begin{pmatrix}
r^2 x \\ \alpha (\alpha y - z) - ry + r \alpha x \\ r(\alpha y - z)
\end{pmatrix} & \hspace{-3mm}\text{if } x > 0,\ z < 0,\ y < 0,\ \alpha y - z < 0, \\
& \\
\hspace{-1.5mm} P_4 \begin{pmatrix} x \\ y \\ z \end{pmatrix} = \begin{pmatrix}
-r (\alpha y - x) \\ - \alpha (\alpha y - z) - \alpha (\alpha y - x) + ry \\ -r (\alpha y - z)
\end{pmatrix} & \hspace{-3mm}\text{if } x > 0,\ z < 0,\ y < 0,\ \alpha y - z > 0,
\end{array}
\right.
\end{align}
with the matrices $P_1$, $P_2$, $P_3$ and $P_4$ respectively defined as:
\begin{align}
\label{EQUATCollisionMatric_P_i_}
P_1= \begin{pmatrix}
                -r & r\alpha & 0 \\
				 -\alpha & \alpha^2- r & r\alpha \\
				 0 & 0  & r^2 \\
	 \end{pmatrix}, \hspace{2mm} 
P_2= \begin{pmatrix}
				 r & -r\alpha & 0 \\
				 \alpha & -2\alpha^2+ r & \alpha \\
				 0 & -r\alpha  & r \\
	 \end{pmatrix}, \hspace{2mm}
&P_3= \begin{pmatrix}
				 r^2 & 0 & 0 \\
				 r\alpha & \alpha^2- r & -\alpha \\
				 0 & r\alpha  & -r \\
	\end{pmatrix}, \hspace{2mm}
P_4=P_2.
\end{align}
The case when $x < 0, z > 0$ is treated by symmetry, defining $\mathfrak{P}(u) = -\mathfrak{P}\big(-u\big)$, where $\mathfrak{P}\big(-u\big)$ is defined in \eqref{EQUATCollisionMatric_P_i_}.\\
In other words, we have:
\begin{align}
\widehat{\mathfrak{P}}(u) = \frac{\mathfrak{P}(u)}{ \big\vert \mathfrak{P}(u) \big\vert }\hspace{3mm} \forall u = \hspace{1mm}^t\hspace{-0.25mm}(x,y,z) \in X \hspace{2mm} \text{such that} \hspace{2mm} x \neq 0,\, z \neq 0,\, \alpha y - x \neq 0 \text{  and  } \alpha y - z \neq 0.
\end{align}

Given the symmetries of the system, we focus on the configurations for which $x > 0$, $z < 0$, and $y > 0$. The case $y < 0$ is deduced by considering the transformation $\mathbb{R}^3 \supset X \ni \hspace{0.5mm}^t\hspace{-0.25mm} (x,y,z) \rightarrow \hspace{0.5mm}^t\hspace{-0.25mm} (-z,-y,-x)$.\\
\newline
We assume first that $y>0$ and $\alpha y-x>0$, where $\alpha$ is defined in \eqref{EQUATDefinAlpha}. The meaning of the condition on $\alpha y -x$ will become clear after the computation of the first collision. We denote by $u(0) = \hspace{0.5mm}^t\hspace{-0.25mm} (x,y,z) \in X$ the vector normal to the plane $\mathcal{P}(0)$ describing the initial configuration of the system. After the initial configuration, corresponding to the case when a collision of type $\mathfrak{b}$ just took place, the condition $y > 0$ implies that the next collision is of type $\mathfrak{a}$. Indeed, the vector of the initial positions $p(0)$ is colinear to:
\begin{align}
u(0)\wedge e_y=\begin{pmatrix} -z\\ 0\\x\end{pmatrix}
\end{align}
(observe that the assumptions $x,-z > 0$ are such that the entries of $u(0)\wedge e_y$ are positive, in agreement with the fact that this vector represents relative distances between the particles). The vector $q(0)$ of the initial relative velocities normal to $u(0)$ is then:
\begin{align}
q(0)= p(0) \wedge u(0) = \begin{pmatrix} -xy \\ x^2+z^2 \\ -yz \end{pmatrix}
\end{align} 
(observe that the second entry of $q(0)$ is always positive, implying that the pair \footnotesize{\tikz[baseline=(char.base)]{\node[shape=circle,draw,inner sep=2pt] (char) {2};}}\normalsize{}-\footnotesize{\tikz[baseline=(char.base)]{\node[shape=circle,draw,inner sep=2pt] (char) {3};}}\normalsize{} is separating). We prove now the following statement. When evolving on the intersection between the unit sphere and the plane $\mathcal{P}(0)$ normal to $u(0)$, the first plane that is intersected between $\{x = 0\}$ and $\{z = 0\}$ is determined by the scalar product between $q(0)$ and the vector $v(0) = u(0) - \big(u(0)\cdot e_y\big)e_y =  \hspace{0.5mm}^t\hspace{-0.25mm} (x,0,z)$.\\
To see that the next collision is determined by the sign of $q(0)\cdot v(0)$, for $\lambda > 0$ we consider the line $t \mapsto p(0) + \big(q(0) - \lambda p(0)\big) t$. The term $-\lambda p(0)$ ensures that the velocity reaches at least one of the two planes $\{x = 0\}$ or $\{z = 0\}$ in finite positive time (and the choice of $\lambda$ plays no role in determining the next collisions that take place, according to Theorem 4.1 in \cite{DoHR025}). The line intersects the planes $\{x = 0\}$ and $\{z = 0\}$, respectively at times $t_x$ and $t_z$ given by:
\begin{align}
t_x = \frac{-z}{xy + \lambda(-z)}, \hspace{5mm} t_z = \frac{x}{yz+\lambda x},
\end{align}
so that in the case when $y > 0$, $t_x$ is always positive, while $t_z$ might have both signs. More precisely, if $\lambda < y(-z)/x$, $t_z < 0$, and $t_z > 0$ if $\lambda > y(-z)/x$. For $\lambda > 0$ small enough, relying on Theorem 4.1 in \cite{DoHR025}, we clearly see that only collision takes place in the future, which has to be of type $\mathfrak{a}$. To see that the first collision to take place is necessarily of this type, without relying on the result of \cite{DoHR025}, we compute:
\begin{align}
t_x - t_z = \frac{y (x^2 + z^2)}{- x(-z) \lambda^2 + \big[yz^2-x^2y\big] \lambda + xy^2(-z)} \cdotp
\end{align}
The denominator is a quadratic polynomial in $\lambda$, whose discriminant is the perfect square $y^2\big(x^2+z^2\big)^2$. Observing in addition that this polynomial vanishes at $\lambda = y(-z)/x$ and that its derivative is negative at this point, we deduce that the polynomial has no root larger than $y(-z)/x$, proving that $t_x < t_z$ in the case when $t_z$ is positive. In summary, if $y > 0$, then $0 < t_x < t_z$ or $t_z < 0 < t_x$, and conversely if $y < 0$, then $0 < t_z < t_x$ or $t_x < 0 < t_z$. In other words, the next collision to take place is of type $\mathfrak{a}$ when $y > 0$, and of type $\mathfrak{c}$ when $y < 0$.\\
Besides, since we have:
\begin{align}
q(0) \cdot v(0) = -y(x^2+z^2),
\end{align}
we deduce that a collision of type $\mathfrak{c}$ follows if $q(0)\cdot v(0) > 0$, and $\mathfrak{a}$ follows if $q(0)\cdot v(0) < 0$.\\
\newline
We compute then the normal vector $u_\mathfrak{a}(1)$ to the plane $\mathcal{P}_\mathfrak{a}(1) = \text{Span}\big[p_\mathfrak{a}(1),q_\mathfrak{a}(1)\big]$ when the first collision takes place. It is colinear to:
\[
q_{\mathfrak{a}}(1)\wedge p_{\mathfrak{a}}(1)= \underbrace{Aq(0)}_{=q_{\mathfrak{a}}(1)} \wedge \underbrace{[e_x \wedge u(0)]}_{=p_{\mathfrak{a}}(1)},
\] 
where $A$ is the first matrix given in \eqref{EQUATCollision_Matri}. We have:
\begin{align}
p_\mathfrak{a}(1) = e_x \wedge u(0) =\begin{pmatrix} 0 \\-z\\y \end{pmatrix}
\hspace{5mm} \text{and} \hspace{5mm}
q_\mathfrak{a}(1) = Aq(0)= \begin{pmatrix}
			-r & 0 & 0 \\
			\alpha & 1 & 0 \\
			0& 0 & 1 \\
		\end{pmatrix}   \begin{pmatrix} -xy \\ x^2+z^2 \\ -yz \end{pmatrix}= \begin{pmatrix} rxy \\ -\alpha xy + x^2 + z^2 \\ -yz \end{pmatrix}.
\end{align}
Hence,
\begin{align}
q_{\mathfrak{a}}(1)\wedge p_{\mathfrak{a}}(1) = \begin{pmatrix} rxy \\ -\alpha xy + x^2 + z^2 \\ -yz \end{pmatrix} \wedge \begin{pmatrix} 0 \\-z\\y \end{pmatrix} = \begin{pmatrix} -\alpha xy^2+x^2y \\ -rxy^2 \\ -rxyz\end{pmatrix}
\end{align}
which is colinear to the following vector, that we denote by $u_\mathfrak{a}(1)$:
\begin{equation}
\label{EQUATLinea__P__u_a__}
u_\mathfrak{a}(1) = \begin{pmatrix} x-\alpha y \\ -ry \\ -rz \end{pmatrix}.
\end{equation}
Turning now to the second collision, we rely on the same arguments we used for the first collision, and we determine its type by computing the scalar product $q(1)\cdot v(1) = \big(p(1)\wedge u_\mathfrak{a}(1)\big) \cdot v(1)$, with $q(1) = p(1) \wedge u_\mathfrak{a}(1)$, $p(1) = u_\mathfrak{a}(1) \wedge e_x$ and $v(1) = u_\mathfrak{a}(1) - \big( u_\mathfrak{a}(1) \cdot e_x \big)e_x$. If we have $q(1) \cdot v(1) > 0$, then the second collision is of type $\mathfrak{b}$, and if $q(1) \cdot v(1) < 0$, the second collision is of type $\mathfrak{c}$. We have:
\begin{align}
\label{EQUATCompu_q(1)}
q(1)\cdot v(1) = \big(p(1)\wedge u_\mathfrak{a}(1)\big) \cdot v(1) = \Big( \begin{pmatrix} 0 \\ -rz \\ ry \end{pmatrix} \wedge \begin{pmatrix} x-\alpha y \\ -ry \\ -rz \end{pmatrix} \Big) \cdot \begin{pmatrix} 0 \\ -ry \\ -rz \end{pmatrix} = r^2 (y^2+z^2) (\alpha y - x).
\end{align}
Therefore, the assumption $\alpha y - x > 0$ implies that the second collision is of type $\mathfrak{b}$.\\
We compute now the normal vector $u_\mathfrak{ab}(2)$ to the plane $\mathcal{P}_\mathfrak{ab}(2) = \text{Span}\big[ p_\mathfrak{ab}(2),q_\mathfrak{ab}(2) \big]$ associated to the configuration of the system after this second collision. $u_\mathfrak{ab}(2)$ is colinear, and has the same orientation as $q_\mathfrak{ab}(2) \wedge p_\mathfrak{ab}(2)$, where:
\begin{align}
p_\mathfrak{ab}(2) = e_y \wedge u_\mathfrak{a}(1) = \begin{pmatrix} 0 \\ 1 \\ 0 \end{pmatrix} \wedge \begin{pmatrix} x-\alpha y \\ -ry \\ -rz \end{pmatrix} = \begin{pmatrix} -rz \\ 0 \\ \alpha y - x \end{pmatrix}
\end{align}
and
\begin{align}
q_\mathfrak{ab}(2) = B q(1) = \begin{pmatrix} 1 & \alpha & 0 \\ 0 & -r & 0 \\ 0 & \alpha & 1 \end{pmatrix} \begin{pmatrix} r^2(y^2+z^2) \\ ry(x - \alpha y) \\ rz (x- \alpha y) \end{pmatrix} = \begin{pmatrix} r^2(y^2+z^2) + r\alpha y(x - \alpha y) \\ -r^2 y (x -\alpha y) \\ r(\alpha y + z)(x - \alpha y) \end{pmatrix}.
\end{align}
We find then:
\begin{align}
q_\mathfrak{ab}(2) \wedge p_\mathfrak{ab}(2) &= \begin{pmatrix} r^2(y^2+z^2) + r\alpha y(x - \alpha y) \\ -r^2 y (x -\alpha y) \\ r(\alpha y + z)(x - \alpha y) \end{pmatrix} \wedge \begin{pmatrix} -rz \\ 0 \\ \alpha y - x \end{pmatrix} \nonumber\\
&= \begin{pmatrix}
r^2 y (\alpha y - x)^2 \\
-r^2 z (\alpha y + z)(x-\alpha y) - r^2(y^2+z^2)(\alpha y - x) + r\alpha y (\alpha y - x)^2 \\
-r^3 y z (x - \alpha y)
\end{pmatrix},
\end{align}
which is a vector colinear and with the same orientation as:
\begin{align}
\begin{pmatrix}
ry(\alpha y - x) \\
rz(\alpha y + z) - r(y^2+z^2) + \alpha y(\alpha y - x) \\
r^2 yz
\end{pmatrix}.
\end{align}
Observing that $rz(\alpha y + z) - r(y^2 + z^2) = r\alpha yz - ry^2 = ry(\alpha z - y)$, we can simplify even more and obtain that $q_\mathfrak{ab}(2) \wedge p_\mathfrak{ab}(2)$ is colinear and has the same orientation as the following vector, that we denote by $u_\frak{ab}(2)$:
\begin{align}
\label{EQUATLinea__P__u_ab_}
u_\frak{ab}(2) =
\begin{pmatrix}
r(\alpha y - x) \\
r(\alpha z - y) + \alpha (\alpha y - x) \\
r^2 z
\end{pmatrix}.
\end{align}
The expression of \eqref{EQUATLinea__P__u_ab_}, which describes the configuration of the particle system after the first collision of type $\mathfrak{b}$, corresponds then to the expression of $\mathfrak{P}\big( \hspace{0.5mm}^t\hspace{-0.5mm}(x,y,z)\big)$, on the subset $y > 0$, $\alpha y - x > 0$. Therefore $\widehat{\mathfrak{P}}$, restricted on this subset, coincides with a projective transformation.\\
\newline
We turn now to the case when $y > 0$, $\alpha y - x < 0$. The first assumption implies that the first collision is of type $\mathfrak{a}$, already studied in the previous case, so that we restart from the normal vector $u_\mathfrak{a}(1)$ to the plane $\mathcal{P}_\mathfrak{a} = \text{Span}\big[p_\mathfrak{a}(1),q_\mathfrak{a}(1)\big]$, given by the expression \eqref{EQUATLinea__P__u_a__}. The assumption $\alpha y - x < 0$ implies this time that the second collision is of type $\mathfrak{c}$. The configuration of the system right after this second collision is given by the following position and velocity vectors:
\begin{align}
p_\mathfrak{ac}(2) = e_z \wedge u_\mathfrak{a}(1) = \begin{pmatrix} 0 \\ 0 \\ 1 \end{pmatrix} \wedge \begin{pmatrix} x-\alpha y \\ -ry \\ -rz \end{pmatrix} = \begin{pmatrix} ry \\ x-\alpha y \\ 0 \end{pmatrix}
\end{align}
and $q_\mathfrak{ac}(2) = Cq(1)$ where $q(1) = p(1) \wedge u_\mathfrak{a}(1)$ was computed in \eqref{EQUATCompu_q(1)}, so that:
\begin{align}
q_\mathfrak{ac}(2) =
\begin{pmatrix}
1 & 0 & 0 \\ 0 & 1 & \alpha \\ 0 & 0 & -r
\end{pmatrix}
\begin{pmatrix}
r^2(y^2+z^2) \\ ry(x-\alpha y) \\ rz(x-\alpha y)
\end{pmatrix}
= \begin{pmatrix}
r^2(y^2+z^2) \\ ry(x-\alpha y) + r\alpha z(x-\alpha y) \\ -r^2 z(x-\alpha y)
\end{pmatrix}
\end{align}
so that:
\begin{align}
q_\mathfrak{ac}(2) \wedge p_\mathfrak{ac}(2) &= \begin{pmatrix}
r^2(y^2+z^2) \\ ry(x-\alpha y) + r\alpha z(x-\alpha y) \\ -r^2 z(x-\alpha y)
\end{pmatrix}
\wedge
\begin{pmatrix} ry \\ x-\alpha y \\ 0 \end{pmatrix} \nonumber\\
&= r\begin{pmatrix}
rz(x-\alpha y)^2 \\ -r^2yz(x-\alpha y) \\ r(y^2+z^2)(x-\alpha y) - ry^2(x-\alpha y) - r\alpha y z(x-\alpha y)
\end{pmatrix},
\end{align}
which is colinear, and has the same direction (keeping in mind that $z < 0$) as the following vector, that we denote by $u_\mathfrak{ac}(2)$:
\begin{align}
u_\mathfrak{ac}(2) = \begin{pmatrix} \alpha y - x \\ r y \\ \alpha y - z \end{pmatrix}.
\end{align}
We compute now the third collision. We pose:
\begin{align}
p(2) = u_\mathfrak{ac}(2) \wedge e_z = \begin{pmatrix} ry \\ x-\alpha y \\ 0 \end{pmatrix}, \hspace{3mm} q(2) = p(2) \wedge u_\mathfrak{ac}(2) = \begin{pmatrix} (x-\alpha y)(\alpha y - z) \\ -ry(\alpha y - z) \\ r^2y^2 + (x-\alpha y)^2 \end{pmatrix},
\end{align}
and we deduce that the third collision, following $\mathfrak{a}$ and $\mathfrak{c}$, is necessarily of type $\mathfrak{b}$ by computing $q(2) \cdot v(2) < 0$ with $v(2) = u_\mathfrak{ac}(2) - \big(u_\mathfrak{ac} \cdot e_z \big)e_z$. We recover here the result of Proposition 4.5 in \cite{DoHR025}. The configuration of the system after this third collision is given by the two vectors:
\begin{align}
q_\mathfrak{acb}(3) = Bq(2)
&= \begin{pmatrix}
1 & \alpha & 0 \\
0 & -r & 0 \\
0 & \alpha & 1 \\
\end{pmatrix}
\begin{pmatrix} (x-\alpha y)(\alpha y - z) \\ -ry(\alpha y - z) \\ r^2y^2 + (x-\alpha y)^2 \end{pmatrix} \nonumber\\
&= \begin{pmatrix}
\big(x-(r+1)\alpha y\big)(\alpha y -z) \\
r^2 y (\alpha y - z) \\
-r\alpha y (\alpha y - z) + r^2y^2 + (x - \alpha y)^2
\end{pmatrix}
\end{align}
and
\begin{align} 
p_{acb}(3) = e_y \wedge u_{\mathfrak{ac}}(2) = \begin{pmatrix}
\alpha y - z \\ 0 \\ x - \alpha y
\end{pmatrix}.
\end{align}
Therefore, the plane spanned by $p_\mathfrak{acb}(3)$ and $q_\mathfrak{acb}(3)$ is normal to:
\begin{align}
q_\mathfrak{acb}(3) \wedge p_\mathfrak{acb}(3) &= \begin{pmatrix}
\big(x-(r+1)\alpha y\big)(\alpha y -z) \\
r^2 y (\alpha y - z) \\
-r\alpha y (\alpha y - z) + r^2y^2 + (x - \alpha y)^2
\end{pmatrix}
\wedge
\begin{pmatrix}
\alpha y - z \\ 0 \\ x - \alpha y
\end{pmatrix} \nonumber\\
&= \begin{pmatrix}
r^2 y (x-\alpha y)(\alpha y - z) \\
-r\alpha y(\alpha y - z)^2 + r^2y^2(\alpha y - z) + r\alpha y(\alpha y - z)(x - \alpha y) \\
-r^2 y(\alpha y - z)^2
\end{pmatrix}
\end{align}
which is colinear and has the same orientation of the following vector, that we denote by $u_\mathfrak{acb}(3)$:
\begin{align}
u_{\mathfrak{acb}}(3)= \begin{pmatrix} r(x-\alpha y) \\ -\alpha (\alpha y - z) + ry + \alpha (x - \alpha y) \\ -r(\alpha y- z) \end{pmatrix}.
\end{align}
The configuration described by $u_{\mathfrak{acb}}(3)$ represents the state of the system right after the first collision of type $\mathfrak{b}$ that follows the initial configuration, in the case when $y > 0$ and $\alpha y - x < 0$. We have therefore $\widehat{\mathfrak{P}}\big(\hspace{0.25mm}^t\hspace{-0.25mm}(x,y,z)\big) = u_\mathfrak{acb}(3) / \vert u_\mathfrak{acb}(3) \vert$ on this subset, which proves that the restriction of $\widehat{\mathfrak{P}}$ to $y > 0$, $\alpha y - x < 0$ is also a projective transformation.\\
The cases when $y < 0$ being treated by symmetry, the proof of Theorem \ref{THEOR__P__FukngLinea} is complete.

\label{PROPOEigen_P_1_}
If $r \in\ ]0,7-4\sqrt{3}]$, the three eigenvalues $\lambda_{P_1,i}$, $1 \leq i \leq 3$, of the matrix $P_1$ (defined in \eqref{EQUATCollisionMatric_P_i_}) are real and given by the expressions:
\begin{gather}
\lambda_{P_1,1} = r^2,\nonumber\\
\begin{align}
\lambda_{P_1,2} = \frac{r^2-6r+1 - (r+1)\sqrt{r^2-14r+1}}{8},\hspace{3mm} \lambda_{P_1,3} = \frac{r^2-6r+1 + (r+1)\sqrt{r^2-14r+1}}{8}.
\end{align}
\end{gather}
We have:
\begin{align}
0 < \lambda_{P_1,1} < \lambda_{P_1,2} < \lambda_{P_1,3}.
\end{align}
If $r \in\ ]7-4\sqrt{3},1]$, only one eigenvalue $\lambda_{P_1,1}$ of $P_1$ is real, while the two other eigenvalues $\lambda_{P_1,i}$, $i =2,3$ are complex conjugated. The eigenvalues are given by the expressions:
\begin{gather}
\lambda_{P_1,1} = r^2,\nonumber\\
\begin{align}
\lambda_{P_1,2} = \frac{r^2-6r+1 - i(r+1)\sqrt{ \vert r^2-14r+1 \vert }}{8},\hspace{3mm} \lambda_{P_1,3} = \frac{r^2-6r+1 + i(r+1)\sqrt{ \vert r^2-14r+1 \vert }}{8},
\end{align}
\end{gather}
and we have:
\begin{align}
0 < \lambda_{P_1,1} < \vert \lambda_{P_1,2} \vert = \vert \lambda_{P_1,3} \vert = r.
\end{align}
For any $r \in\ ]0,1]$, the eigenspace associated to $\lambda_{P_1,1}$ is $\text{Vect}\{(\alpha,r+1,3\alpha)\}$.\\
If $r \in\ ]0,7-4\sqrt{3}]$, the eigenspaces associated respectively to $\lambda_{P_1,i}$, $i = 2,3$, are subsets of the hyperplane $\{(x,y,z) \in \mathbb{R}^3\ /\ z=0 \}$, which is invariant under the action of $P_1$, and complementary in $\mathbb{R}^3$ with the eigenspace associated to $\lambda_{P_1,1}$. The eigenspaces respectively associated to $\lambda_{P_1,2}$ and $\lambda_{P_1,3}$ are:
\begin{align}
\label{EQUATEigenspace_P_1_Domin}
\text{Vect}\{(2r,\alpha \mp \sqrt{\alpha^2-4r},0)\} \hspace{5mm} \text{with } \mp = - \text{ if } i=2, \pm = + \text{ if } i=3.
\end{align}
If $r \in\ ]7-4\sqrt{3},1]$, the hyperplane $\{(x,y,z) \in \mathbb{R}^3\ /\ z=0 \}$ is invariant under the action of $P_1$, and complementary in $\mathbb{R}^3$ with the eigenspace associated to $\lambda_{P_1,1}$, and $P_1$ restricted to this hyperplane writes:
\begin{align}
{                                            
  \left.\kern-\nulldelimiterspace                                           
  P_1               
  \mathchoice{\vphantom{\big|}}{}{}{}                                              
  \right|_{\{z=0\}}                        
  } = \begin{pmatrix} \frac{r^2-6r+1}{8} & \frac{(r+1)\sqrt{ \vert r^2-14r+1 \vert }}{8} \\
-\frac{(r+1)\sqrt{ \vert r^2-14r+1 \vert }}{8} & \frac{r^2-6r+1}{8} \end{pmatrix}
\end{align}
in the basis $\big(\mathfrak{Re}(u_2),\mathfrak{Im}(u_2)\big)$, where $u_2$ is an eigenvector associated to the eigenvalue $\lambda_{P_1,2}$.

The characteristic polynomial of the matrix $P_1$ is $\chi_{P_1}(\lambda) = (\lambda - r^2) \big[ \lambda^2 + (2r-\alpha^2) \lambda + r^2 \big]$, and its determinant is $\det(P_1) = r^4$.\\
Therefore, $\lambda_{P_1,1} = r^2$ is an eigenvalue of $P_1$, associated to the one-dimensional eigenspace $\text{Vect}\{(\alpha,r+1,3\alpha)\}$ given by the intersection of the two hyperplanes $E_1 = \{(x,y,z) \in \mathbb{R}^3\ /\ (r+1)x = \alpha y\}$ and $E_2 = \{(x,y,z) \in \mathbb{R}^3\ /\ \alpha x + (r^2+r-\alpha^2) y - r \alpha z = 0\}$. Besides, the hyperplane $E_3 = \{(x,y,z) \in \mathbb{R}^3\ /\  z=0 \}$ is invariant under the action of $P_1$. Since $r \neq 0$, the intersection between the three planes $E_1 \cap E_2 \cap E_3$ is reduced to $\{0\}$, and so the action of $P_1$ on $\mathbb{R}^3$ can be decomposed into its action, on the one hand, on the invariant line $E_1 \cap E_2$ (associated to the eigenvalue $\lambda_{P_1,1} = r^2$), and on the other hand on invariant hyperplane $E_3$ (associated to the two other eigenvalues).\\
The three eigenvalues of $P_1$ are real if and only if the discriminant $\Delta_{P_1}$ of $\lambda^2 + (2r-\alpha^2) \lambda + r^2$ is non-negative. Since we have:
\begin{align*}
\Delta_{P_1} = \alpha^2(\alpha^2 -4r) = \frac{\alpha^2}{4}(r^2-14r+1),
\end{align*}
the two roots of $r^2 - 14r + 1$ are $7 \pm 4\sqrt{3}$, and only $7 - 4\sqrt{3} \simeq 0.0718$ belongs to $[0,1]$. The three eigenvalues of $P_1$ are then real if and only if $r \leq 7-4\sqrt{3}$. In this case, the eigenvalues different from $\lambda_{P_1,1} = r^2$ are:
\begin{align}
\lambda_{P_1,i} = \frac{r^2-6r+1 \mp(r+1)\sqrt{r^2-14r+1}}{8} \hspace{5mm} \text{with}\ i=2\ \text{or}\ 3.
\end{align}
We will denote by $\lambda_{P_1,3}$ the eigenvalue obtained when $\mp = +$. In the case when $\lambda_{P_1,i}$, $i =2,3$, are real, we have $0 \leq r^2 \leq \lambda_{P_1,i}$ for any $r \in [-1,7-4\sqrt{3}]$, with equality only if $r=0$ or $r=-1$. Therefore:
\begin{align}
0 < \lambda_{P_1,1} < \lambda_{P_1,i} \hspace{5mm} \forall r \in\ ]0,7-4\sqrt{3}],
\end{align}
so that $\lambda_{P_1,3}$ is the dominating eigenvalue for any $r \in\ ]0,7-4\sqrt{3}]$.\\
In the case when the eigenvalues $\lambda_{P_1,i}$ ($i = 2,3$) are complex, relying on the determinant of $P_1$ we have $\vert \lambda_{P_1,i} \vert = r$, so that $\lambda_{P_1,i}$, $i =2,3$, are the dominating eigenvalues in the case when $r \in\ ]7-4\sqrt{3},1]$.

\label{PROPOEigen_P_2_}
If $r \in\ ]0,3-2\sqrt{2}]$, the three eigenvalues $\lambda_{P_2,i}$, $1 \leq i \leq 3$, of the matrix $P_2$ (defined in \eqref{EQUATCollisionMatric_P_i_}) are real and given by the expressions:
\begin{gather}
\lambda_{P_2,1} = r,\nonumber\\
\begin{align}
\lambda_{P_2,2} = r - \alpha^2 + \alpha \sqrt{\alpha^2 - 2r},\hspace{3mm} \lambda_{P_2,3} = r - \alpha^2 - \alpha \sqrt{\alpha^2 - 2r}.
\end{align}
\end{gather}
We have:
\begin{align}
\lambda_{P_2,3} < \lambda_{P_2,2} < 0 \hspace{5mm} \text{and} \hspace{5mm} \vert \lambda_{P_2,2} \vert < \lambda_{P_2,1} < \vert \lambda_{P_2,3} \vert.
\end{align}
If $r \in\ ]3-2\sqrt{2},1]$, only one eigenvalue $\lambda_{P_2,1}$ of $P_2$ is real, while the two other eigenvalues $\lambda_{P_2,i}$, $i =2,3$ are complex conjugated. The eigenvalues are given by the expressions:
\begin{gather}
\lambda_{P_2,1} = r,\nonumber\\
\begin{align}
\lambda_{P_2,2} = r - \alpha^2 + i \alpha \sqrt{\alpha^2 - 2r},\hspace{3mm} \lambda_{P_2,3} = r - \alpha^2 - i \alpha \sqrt{\alpha^2 - 2r},
\end{align}
\end{gather}
and we have:
\begin{align}
\lambda_{P_2,1} = \vert \lambda_{P_2,2} \vert = \vert \lambda_{P_2,3} \vert = r.
\end{align}
For any $r \in\ ]0,1]$, the eigenspace associated to $\lambda_{P_2,1}$ is $\text{Vect}\{(1,0,-1)\}$.\\
If $r \in\ ]0,3-2\sqrt{2}]$, the eigenspaces associated respectively to $\lambda_{P_2,i}$, $i = 2,3$, are subsets of the hyperplane $\{(x,y,z) \in \mathbb{R}^3\ /\ x = z \}$, which is invariant under the action of $P_2$, and orthogonal in $\mathbb{R}^3$ with the eigenspace associated to $\lambda_{P_2,1}$. The eigenspaces respectively associated to $\lambda_{P_2,2}$ and $\lambda_{P_2,3}$ are:
\begin{align}
\label{EQUATEigenspace_P_1_Domin}
\text{Vect}\{(r,\alpha \mp \sqrt{\alpha^2-2r},r)\} \hspace{5mm} \text{with } \mp = - \text{ if } i=2, \pm = + \text{ if } i=3.
\end{align}
If $r \in\ ]3-2\sqrt{2},1]$, the hyperplane $\{(x,y,z) \in \mathbb{R}^3\ /\ x = z \}$ is invariant under the action of $P_2$, and orthogonal in $\mathbb{R}^3$ with the eigenspace associated to $\lambda_{P_2,1}$, and $P_2$ restricted to this hyperplane writes:
\begin{align}
{                                            
  \left.\kern-\nulldelimiterspace                                           
  P_2               
  \mathchoice{\vphantom{\big|}}{}{}{}                                              
  \right|_{\{x=z\}}                        
  } = \begin{pmatrix} r-\alpha^2 & -\alpha \sqrt{ \vert \alpha^2-2r \vert } \\
\alpha \sqrt{ \vert \alpha^2-2r \vert } & r-\alpha^2 \end{pmatrix}
\end{align}
in the basis $\big(\mathfrak{Re}(u_2),\mathfrak{Im}(u_2)\big)$, where $u_2$ is an eigenvector associated to the eigenvalue $\lambda_{P_2,2}$.

The characteristic polynomial of the matrix $P_2$ is $\chi_{P_2}(\lambda) = (\lambda - r) \big[ \lambda^2 + (2\alpha^2 - 2r) \lambda + r^2 \big]$, and its determinant is $\det(P_2) = r^3$. $\lambda_{P_2,1} = r$ is an eigenvalue of $P_2$, associated to the one-dimensional eigenspace $E_4 = \text{Vect}\{(1,0,-1)\}$. In addition, the hyperplane $E_5 = \{(x,y,z) \in \mathbb{R}^3\ /\ x=z \}$ is invariant under the action of $P_2$. In addition, $E_4$ and $E_5$ are orthogonal.\\
The eigenvalues of $P_2$ are all real if and only if the discriminant $\Delta_{P_2}$ of $\lambda^2 + (2\alpha^2 - 2r)\lambda + r^2$ is non-negative. We have here:
\begin{align}
\Delta_{P_2} = 4 \alpha^4 - 8 r \alpha^2 = 4 \alpha^2 (\alpha^2 - 2r) = \alpha^2 ( r^2 - 6r + 1),
\end{align}
the two roots of $r^2 - 6r + 1$ are $3 \pm 2\sqrt{2}$, and only $3 - 2\sqrt{2} \simeq 0.1716$ belongs to $[0,1]$. Therefore, the three eigenvalues of $P_2$ are real if and only if $r \leq 3 - 2\sqrt{2}$. In this case, the eigenvalues different from $\lambda_{P_2,1} = r$ are:
\begin{align}
\lambda_{P_2,i} = r - \alpha^2 \pm \alpha \sqrt{\alpha^2 - 2r} \hspace{5mm} \text{with}\ i=2\ \text{or}\ 3.
\end{align}
We will denote by $\lambda_{P_2,2}$ the eigenvalue obtained when $\pm = +$, and by $\lambda_{P_2,3}$ the eigenvalue obtained when $\pm = -$. Since $r \neq 0$, $r-\alpha^2 = -\frac{1}{4}(1-r)^2 \leq 0$ and $(r - \alpha^2)^2 > \alpha^2(\alpha^2 - 2r)$, we deduce that $\lambda_{P_2,i} < 0$ for $i = 2,3$. Writing in addition the eigenvalues as:
\begin{align}
\lambda_{P_2,i} = -r - \sqrt{\alpha^2-2r} \big[ \sqrt{\alpha^2 - 2r} \mp \alpha \big],
\end{align}
we deduce $\vert \lambda_{P_2,2} \vert \leq \lambda_{P_2,2} \leq \vert \lambda_{P_2,3} \vert$.\\
In the case when $r > 3 - 2\sqrt{2}$, since $\lambda_{P_2,1} = r$, the determinant of $P_2$ allows to deduce that the three eigenvalues have the same modulus, equal to $r$.

\label{THEORStabi____132312}
Let $\lambda_{132^J}^\text{dom}$ be the dominating eigenvalue of the matrix $J P_2 P_3 P_1$, always real for any $0 \leq r \leq 1$, and let $u_{\lambda_{132^J}^\text{dom}}$ be its associated eigenvector                                                              
. Let $r_{\text{crit},132^J}$ be the only root in $]0,1[$ of the equation:
\begin{align}
\alpha \big( u_{\lambda_{132^J}^\text{dom}} \big)_y - \big( u_{\lambda_{132^J}^\text{dom}} \big)_x = 0,
\end{align}
so that we have:
\begin{align}
\label{EQUATTheorr_cr2_132J}
r_{\text{crit},132^J} \simeq 0.2200\ 6978\ 6146\ 3104\ 7521.
\end{align}
Then, for any $r \in\ ]r_{\text{crit},132^J},1[$, there exists a single point in the domain of $\widehat{\mathfrak{P}}_r$ which generates the periodic orbit $132312$ and this orbit is locally stable. This point is given by $u_{\lambda_{132^J}^\text{dom}} / \vert u_{\lambda_{132^J}^\text{dom}} \vert$.

The characteristic polynomial $\chi_{\widetilde{P}_{132^J}}$ of the reduced collision matrix $\widetilde{P}_{132^J} = J P_2 P_3 P_1$ (with $J$ defined in \eqref{EQUATDefin__J__}) is given by the expression:
\begin{align}
\chi_{\widetilde{P}_{132^J}}(\lambda) &= \lambda^3 + \frac{\big(7r^6-24r^5-29r^4+21r^2-8r+1\big)}{32} \lambda^2 \nonumber\\
&\hspace{50mm}+ \frac{\big(r^{11}-8r^{10}+21r^9-29r^7-24r^6+7r^5\big)}{32} \lambda + r^{11}.
\end{align}
The eigenvalues of the collision matrix $\widetilde{P}_{132^J}$ are plotted on Figure \ref{FIGUREigenvalue_132J} when they are real, as well as their respective moduli on Figure \ref{FIGURModulEigen_132J} in the case when they are real or complex.

